import React, { createContext, useContext } from 'react';
import { Field } from '@formily/core';
import { observer, useField } from '@formily/react';
import { isArr, toArr, isValid } from '@formily/shared';
import {
  InputProps,
  Space,
  SelectProps,
  Tag,
  CascaderProps,
  TreeSelectProps,
  DatePickerProps,
  TimePickerProps
} from '@arco-design/web-react';
import { getDayjsValue as arcoGetDayjsValue } from '@arco-design/web-react/es/_util/dayjs';
import cls from 'classnames';
import { usePrefixCls } from '../__builtins__';

const PlaceholderContext = createContext<React.ReactNode>('-');
const Placeholder = PlaceholderContext.Provider;

const getDayjsValue = (value: any, format: string, placeholder: string) => {
  if (isArr(value)) {
    return value.map(val => arcoGetDayjsValue(val, format) || placeholder);
  }
  return arcoGetDayjsValue(value, format) || placeholder;
};

const usePlaceholder = (value?: any) => {
  const placeholder = useContext(PlaceholderContext) || '-';
  return isValid(value) && value !== '' ? value : placeholder;
};

const getValueByValue = (
  array: any[],
  inputValue: any,
  keyMap?: { inputKey?: string; outputKey?: string; childrenKey?: string },
  path: any[] = []
) => {
  const { inputKey = 'value', outputKey = 'label', childrenKey = 'children' } = keyMap || {};
  let outputValue: any;
  if (isArr(array)) {
    if (isArr(inputValue)) {
      outputValue = inputValue.map(v => getValueByValue(array, v, keyMap, path));
    } else {
      array.forEach(obj => {
        if (outputValue === undefined) {
          const currentPath = [...path, obj?.[outputKey]];
          if (obj?.[inputKey] === inputValue) {
            outputValue = {
              leaf: obj?.[outputKey],
              whole: currentPath,
            };
          } else if (obj?.[childrenKey]?.length) {
            outputValue = getValueByValue(obj?.[childrenKey], inputValue, keyMap, currentPath);
          }
        }
      });
    }
    return outputValue;
  }
  return undefined;
};

const Input: React.FC<React.PropsWithChildren<InputProps>> = (props: InputProps) => {
  const prefixCls = usePrefixCls('form-text');
  return (
    <Space className={cls(prefixCls, props.className)} style={props.style}>
      {props.addBefore}
      {props.prefix}
      {usePlaceholder(props.value)}
      {props.suffix}
      {props.addAfter}
    </Space>
  );
};

const Select: React.FC<React.PropsWithChildren<SelectProps>> = observer((props: SelectProps) => {
  const field = useField<Field>();
  const prefixCls = usePrefixCls('form-select-text');
  const dataSource: any[] = field?.dataSource?.length ? field.dataSource : props?.options?.length ? props.options : [];
  const placeholder = usePlaceholder();
  const getSelected = () => {
    const { value } = props;
    if (props.mode === 'multiple' || props.mode === 'tags') {
      if (props.labelInValue) {
        return isArr(value) ? value : [];
      } else {
        return isArr(value) ? value.map(val => ({ label: val, value: val })) : [];
      }
    } else {
      if (props.labelInValue) {
        return isValid(value) ? [value] : [];
      } else {
        return isValid(value) ? [{ label: value, value }] : [];
      }
    }
  };

  const getLabel = (target: any) =>
    dataSource?.find(item => item.value === target?.value)?.label || target.label || placeholder;

  const getLabels = () => {
    const selected = getSelected();
    if (!selected.length) {
      return placeholder;
    }
    if (selected.length === 1) {
      return getLabel(selected[0]);
    }
    return selected.map((item, key) => <Tag key={key}>{getLabel(item)}</Tag>);
  };
  return (
    <div className={cls(prefixCls, props.className)} style={props.style}>
      {getLabels()}
    </div>
  );
});

const TreeSelect: React.FC<React.PropsWithChildren<TreeSelectProps>> = observer((props: TreeSelectProps) => {
  const field = useField<Field>();
  const placeholder = usePlaceholder();
  const prefixCls = usePrefixCls('form-text');
  const dataSource = field?.dataSource?.length ? field.dataSource : props?.treeData?.length ? props.treeData : [];
  const getSelected = () => {
    const { value } = props;
    if (props.multiple) {
      if (props.labelInValue) {
        return isArr(value) ? value : [];
      } else {
        return isArr(value) ? value.map(val => ({ label: val, value: val })) : [];
      }
    } else {
      if (props.labelInValue) {
        return value ? [value] : [];
      } else {
        return value ? [{ label: value, value }] : [];
      }
    }
  };

  const findLabel = (value: any, ds: any[]): any => {
    for (let i = 0; i < ds?.length; i++) {
      const item = ds[i];
      if (item?.value === value) {
        return item?.label;
      } else {
        const childLabel = findLabel(value, item?.children);
        if (childLabel) {
          return childLabel;
        }
      }
    }
  };

  const getLabels = () => {
    const selected = getSelected();
    if (!selected?.length) {
      return <Tag>{placeholder}</Tag>;
    }
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    return selected.map(({ value, label }, key) => (
      <Tag key={key}>{findLabel(value, dataSource) || label || placeholder}</Tag>
    ));
  };
  return (
    <div className={cls(prefixCls, props.className)} style={props.style}>
      {getLabels()}
    </div>
  );
});

const Cascader: React.FC<React.PropsWithChildren<CascaderProps<any>>> = observer((props: CascaderProps) => {
  const field = useField<Field>();
  const placeholder = usePlaceholder();
  const prefixCls = usePrefixCls('form-text');
  const dataSource: any[] = field?.dataSource?.length ? field.dataSource : props?.options?.length ? props.options : [];
  const getSelected = () => {
    const val = toArr(props.value);
    return props.mode === 'multiple' ? val.map(item => item[item.length - 1]) : val.slice(val.length - 1);
  };
  const getLabels = () => {
    const selected = getSelected();
    const labels = getValueByValue(dataSource, selected)
      ?.filter((item: any) => isValid(item))
      ?.map((item: { whole: any[] }) => item?.whole?.join('/'))
      .join(', ');
    return labels || placeholder;
  };
  return (
    <div className={cls(prefixCls, props.className)} style={props.style}>
      {getLabels()}
    </div>
  );
});

const DatePicker: React.FC<React.PropsWithChildren<DatePickerProps>> = props => {
  const placeholder = usePlaceholder();
  const prefixCls = usePrefixCls('form-text');
  const getLabels = () => {
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore
    const labels = getDayjsValue(props.value, props.format, placeholder);
    return isArr(labels) ? labels.join('~') : labels;
  };
  return <div className={cls(prefixCls, props.className)}>{getLabels()}</div>;
};

const TimePicker: React.FC<React.PropsWithChildren<TimePickerProps>> = props => {
  const placeholder = usePlaceholder();
  const prefixCls = usePrefixCls('form-text');
  const getLabels = () => {
    const labels = getDayjsValue(props.value, props.format || '', placeholder);
    return isArr(labels) ? labels.join('~') : labels;
  };
  return (
    <div className={cls(prefixCls, props.className)} style={props.style}>
      {getLabels()}
    </div>
  );
};

const Text = (props: React.PropsWithChildren<any>) => {
  const prefixCls = usePrefixCls('form-text');
  return (
    <div className={cls(prefixCls, props.className)} style={props.style}>
      {usePlaceholder(props.value)}
    </div>
  );
};

Text.Input = Input;
Text.Select = Select;
Text.TreeSelect = TreeSelect;
Text.Cascader = Cascader;
Text.DatePicker = DatePicker;
Text.TimePicker = TimePicker;
Text.Placeholder = Placeholder;
Text.usePlaceholder = usePlaceholder;

export const PreviewText = Text;

export default PreviewText;
